  /* updateSchlDgnssData - Lee  MS */

UPDATE ACA210 /* 학교진단조사 */
   SET CASE_PRGRS_STTS_SE_CD = #{CASE_PRGRS_STTS_SE_CD}, /* 사례진행상태구분코드 */
       LAST_MDFR_ID = #{USER_ID},                        /* 수정아이디 */
       LAST_MDFCN_DT = SYSDATE                           /* 수정일시 */
 WHERE DGNSS_EXMN_MNG_NO = #{DGNSS_EXMN_MNG_NO}


  /* updateInstDgnssData - Lee  MS */

UPDATE ACA400 /* 기관진단조사 */
   SET CASE_PRGRS_STTS_SE_CD = #{CASE_PRGRS_STTS_SE_CD}, /* 사례진행상태구분코드 */
       LAST_MDFR_ID = #{USER_ID},                        /* 수정아이디 */
       LAST_MDFCN_DT = SYSDATE                           /* 수정일시 */
 WHERE DGNSS_EXMN_MNG_NO = #{DGNSS_EXMN_MNG_NO}
